@Injectable()
export class AppService {
    constructor(
        private readonly config:
            ConfigService
    ) {}

    getDbUrl() {
        return this.config
            .get<string>("DB_URL");
    }
}

@Injectable()
export class UsersService {
    constructor(
        private readonly prisma:
            PrismaService
    ) {}

    findUser(id: string) {
        return this.prisma
            .user
            .findUnique({
                where: { id }
            });
    }
}
